for i, (name, cast, desc) in enumerate(items):
    castdesc = "Characters: " + "; ".join(C[c] for c in cast) + ". "
    batches[i % 4].append(f"{name}.jpg|3:2|{STYLE} {castdesc}{desc}")
for b, lines in zip('pqrs', batches):
    open(f'{b}.txt', 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
print(len(items), [len(b) for b in batches])
